create type "public"."submission_operation" as enum ('create', 'update');

create type "public"."submission_type" as enum ('cube', 'vendor');

  create table "public"."cube_submission_features" (
    "id" bigint generated by default as identity not null,
    "cube_submission_id" bigint not null,
    "feature_id" bigint not null,
    "created_at" timestamp with time zone not null default now()
      );


alter table "public"."cube_submission_features" enable row level security;


  create table "public"."cube_submissions" (
    "id" bigint generated by default as identity not null,
    "submission_id" bigint not null,
    "target_cube_id" bigint,
    "name" text not null,
    "version_type" public.cube_version_type not null,
    "image_url" text not null,
    "brand_id" bigint,
    "proposed_brand_name" text,
    "type_id" bigint,
    "proposed_type_name" text,
    "series_id" bigint,
    "proposed_series_name" text,
    "related_to_id" bigint,
    "release_date" date,
    "release_date_precision" public.date_precision,
    "weight" numeric,
    "size" text,
    "surface_finish" public.cube_surface_finish,
    "discontinued" boolean not null,
    "created_at" timestamp with time zone not null default now(),
    "sub_type" public.cubes_subtypes not null
      );


alter table "public"."cube_submissions" enable row level security;


  create table "public"."cube_vendor_link_submissions" (
    "id" bigint generated by default as identity not null,
    "cube_submission_id" bigint not null,
    "vendor_id" bigint not null,
    "url" text not null,
    "price" numeric not null,
    "available" boolean not null,
    "created_at" timestamp with time zone not null default now()
      );


alter table "public"."cube_vendor_link_submissions" enable row level security;


  create table "public"."submissions" (
    "id" bigint generated by default as identity not null,
    "type" public.submission_type not null,
    "status" public.submission_status not null default 'Pending'::public.submission_status,
    "submitter_note" text,
    "reviewer_note" text,
    "reviewed_by_id" uuid,
    "submitted_by_id" uuid not null default auth.uid(),
    "reviewed_at" timestamp with time zone,
    "submitted_at" timestamp with time zone not null default now(),
    "operation" public.submission_operation not null
      );


alter table "public"."submissions" enable row level security;

CREATE UNIQUE INDEX cube_submission_features_pkey ON public.cube_submission_features USING btree (id);

CREATE UNIQUE INDEX cube_submission_id_feature_id_unique ON public.cube_submission_features USING btree (cube_submission_id, feature_id);

CREATE UNIQUE INDEX cube_submissions_pkey ON public.cube_submissions USING btree (id);

CREATE UNIQUE INDEX cube_vendor_link_submissions_pkey ON public.cube_vendor_link_submissions USING btree (id);

CREATE UNIQUE INDEX submissions_pkey ON public.submissions USING btree (id);

