alter table "public"."cube_submissions" add constraint "cube_submissions_brand_id_fkey" FOREIGN KEY (brand_id) REFERENCES public.brands(id) ON UPDATE CASCADE ON DELETE SET NULL not valid;

alter table "public"."cube_submissions" validate constraint "cube_submissions_brand_id_fkey";

alter table "public"."cube_submissions" add constraint "cube_submissions_related_to_id_fkey" FOREIGN KEY (related_to_id) REFERENCES public.cube_models(id) ON UPDATE CASCADE ON DELETE SET NULL not valid;

alter table "public"."cube_submissions" validate constraint "cube_submissions_related_to_id_fkey";

alter table "public"."cube_submissions" add constraint "cube_submissions_release_date_complete_check" CHECK (((release_date IS NULL) = (release_date_precision IS NULL))) not valid;

alter table "public"."cube_submissions" validate constraint "cube_submissions_release_date_complete_check";

alter table "public"."cube_submissions" add constraint "cube_submissions_series_check" CHECK (((series_id IS NULL) OR (proposed_series_name IS NULL))) not valid;

alter table "public"."cube_submissions" validate constraint "cube_submissions_series_check";

alter table "public"."cube_submissions" add constraint "cube_submissions_series_id_fkey" FOREIGN KEY (series_id) REFERENCES public.cube_series(id) ON UPDATE CASCADE ON DELETE SET NULL not valid;

alter table "public"."cube_submissions" validate constraint "cube_submissions_series_id_fkey";

alter table "public"."cube_submissions" add constraint "cube_submissions_size_check" CHECK ((size ~ '^[0-9]+(\.[0-9]+)?\sx\s[0-9]+(\.[0-9]+)?\sx\s[0-9]+(\.[0-9]+)?$'::text)) not valid;

alter table "public"."cube_submissions" validate constraint "cube_submissions_size_check";

alter table "public"."cube_submissions" add constraint "cube_submissions_submission_id_fkey" FOREIGN KEY (submission_id) REFERENCES public.submissions(id) ON UPDATE CASCADE ON DELETE CASCADE not valid;

alter table "public"."cube_submissions" validate constraint "cube_submissions_submission_id_fkey";

alter table "public"."cube_submissions" add constraint "cube_submissions_target_cube_id_fkey" FOREIGN KEY (target_cube_id) REFERENCES public.cube_models(id) ON UPDATE CASCADE ON DELETE CASCADE not valid;

alter table "public"."cube_submissions" validate constraint "cube_submissions_target_cube_id_fkey";

alter table "public"."cube_submissions" add constraint "cube_submissions_type_check" CHECK (((type_id IS NOT NULL) <> (proposed_type_name IS NOT NULL))) not valid;

alter table "public"."cube_submissions" validate constraint "cube_submissions_type_check";

alter table "public"."cube_submissions" add constraint "cube_submissions_type_id_fkey" FOREIGN KEY (type_id) REFERENCES public.cube_types(id) ON UPDATE CASCADE ON DELETE SET NULL not valid;

alter table "public"."cube_submissions" validate constraint "cube_submissions_type_id_fkey";

alter table "public"."cube_submissions" add constraint "cube_submissions_weight_check" CHECK ((weight > (0)::numeric)) not valid;

