alter table "public"."cube_vendor_link_submissions" validate constraint "cube_vendor_link_submissions_cube_submission_id_fkey";

alter table "public"."cube_vendor_link_submissions" add constraint "cube_vendor_link_submissions_vendor_id_fkey" FOREIGN KEY (vendor_id) REFERENCES public.vendors(id) ON UPDATE CASCADE ON DELETE CASCADE not valid;

alter table "public"."cube_vendor_link_submissions" validate constraint "cube_vendor_link_submissions_vendor_id_fkey";

alter table "public"."submissions" add constraint "submissions_reviewed_by_id_fkey" FOREIGN KEY (reviewed_by_id) REFERENCES public.profiles(user_id) ON UPDATE CASCADE ON DELETE SET NULL not valid;

alter table "public"."submissions" validate constraint "submissions_reviewed_by_id_fkey";

alter table "public"."submissions" add constraint "submissions_submitted_by_id_fkey" FOREIGN KEY (submitted_by_id) REFERENCES public.profiles(user_id) ON UPDATE CASCADE ON DELETE SET NULL not valid;

alter table "public"."submissions" validate constraint "submissions_submitted_by_id_fkey";

set check_function_bodies = off;

CREATE OR REPLACE FUNCTION public.submit_cube(p_operation public.submission_operation, p_submitter_note text DEFAULT NULL::text, p_cube jsonb DEFAULT '{}'::jsonb, p_feature_ids bigint[] DEFAULT '{}'::bigint[], p_vendor_links jsonb DEFAULT '[]'::jsonb)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_user_id uuid := auth.uid();
v_submission_id bigint;
v_cube_submission_id bigint;
v_cube record;
v_vendor_link jsonb;
begin if v_user_id is null then raise exception 'Authentication required' using errcode = '42501';
end if;
select * into v_cube
from jsonb_to_record(p_cube) as cube_data (
        target_cube_id bigint,
        name text,
        version_type public.cube_version_type,
        image_url text,
        brand_id bigint,
        proposed_brand_name text,
        type_id bigint,
        proposed_type_name text,
        series_id bigint,
        proposed_series_name text,
        related_to_id bigint,
        release_date date,
        release_date_precision public.date_precision,
        sub_type public.cubes_subtypes,
        weight numeric,
        size text,
        surface_finish public.cube_surface_finish,
        discontinued boolean
    );
if p_operation = 'create'::public.submission_operation
and v_cube.target_cube_id is not null then raise exception 'Create submissions cannot target an existing cube' using errcode = '22023';
elsif p_operation = 'update'::public.submission_operation
and v_cube.target_cube_id is null then raise exception 'Update submissions require target_cube_id' using errcode = '22023';
end if;
insert into public.submissions (
        type,
        status,
        submitter_note,
        submitted_by_id,
        operation
    )
values (
        'cube'::public.submission_type,
        'Pending'::public.submission_status,
        p_submitter_note,
        v_user_id,
        p_operation
    )
returning id into v_submission_id;
insert into public.cube_submissions (
        submission_id,
        target_cube_id,
        name,
        version_type,
        image_url,
        brand_id,
        proposed_brand_name,
        type_id,
        proposed_type_name,
        series_id,
        proposed_series_name,
        related_to_id,
        release_date,
        release_date_precision,
        sub_type,
        weight,
        size,
        surface_finish,
        discontinued
    )
values (
        v_submission_id,
        v_cube.target_cube_id,
        v_cube.name,
        v_cube.version_type,
        v_cube.image_url,
        v_cube.brand_id,
        v_cube.proposed_brand_name,
        v_cube.type_id,
        v_cube.proposed_type_name,
        v_cube.series_id,
        v_cube.proposed_series_name,
        v_cube.related_to_id,
        v_cube.release_date,
        v_cube.release_date_precision,
        v_cube.sub_type,
        v_cube.weight,
        v_cube.size,
        v_cube.surface_finish,
        v_cube.discontinued
    )
returning id into v_cube_submission_id;
insert into public.cube_submission_features (cube_submission_id, feature_id)
select v_cube_submission_id,
    proposed.feature_id
from (
        select distinct feature_id
        from unnest(p_feature_ids) as values_list(feature_id)
        where feature_id is not null
    ) proposed;
for v_vendor_link in
select value
from jsonb_array_elements(p_vendor_links) loop
insert into public.cube_vendor_link_submissions (
        cube_submission_id,
        vendor_id,
        url,
        price,
        available
    )
values (
        v_cube_submission_id,
        (v_vendor_link->>'vendor_id')::bigint,
        (v_vendor_link->>'url')::text,
        (v_vendor_link->>'price')::numeric,
        (v_vendor_link->>'available')::boolean
    );
end loop;
return v_submission_id;
end;
$function$
;

