  create policy "Enable read access for all users"
  on "public"."cube_series"
  as permissive
  for select
  to public
using (true);



  create policy "Users can only see their submissions"
  on "public"."cube_submission_features"
  as permissive
  for select
  to authenticated
using ((EXISTS ( SELECT 1
   FROM (public.cube_submissions cs
     JOIN public.submissions s ON ((s.id = cs.submission_id)))
  WHERE ((cs.id = cube_submission_features.cube_submission_id) AND (s.submitted_by_id = ( SELECT auth.uid() AS uid))))));



  create policy "Admin and Database Managers can see all rows"
  on "public"."cube_submissions"
  as permissive
  for select
  to authenticated
using ((EXISTS ( SELECT 1
   FROM public.profiles p
  WHERE ((p.user_id = ( SELECT auth.uid() AS uid)) AND (p.role = ANY (ARRAY['Admin'::public.users_roles, 'Database Manager'::public.users_roles]))))));



  create policy "Users can see their own submissions"
  on "public"."cube_submissions"
  as permissive
  for select
  to authenticated
using ((EXISTS ( SELECT 1
   FROM public.submissions s
  WHERE ((cube_submissions.submission_id = s.id) AND (s.submitted_by_id = ( SELECT auth.uid() AS uid))))));



  create policy "Users can only see their submissions"
  on "public"."cube_vendor_link_submissions"
  as permissive
  for select
  to authenticated
using ((EXISTS ( SELECT 1
   FROM (public.cube_submissions cs
     JOIN public.submissions s ON ((s.id = cs.submission_id)))
  WHERE ((cube_vendor_link_submissions.cube_submission_id = cs.id) AND (s.submitted_by_id = ( SELECT auth.uid() AS uid))))));



  create policy "Admins and Database Managers can select submissions"
  on "public"."submissions"
  as permissive
  for select
  to authenticated
using ((EXISTS ( SELECT 1
   FROM public.profiles
  WHERE ((profiles.user_id = auth.uid()) AND (profiles.role = ANY (ARRAY['Admin'::public.users_roles, 'Database Manager'::public.users_roles]))))));



  create policy "Users can only see their own submissions"
  on "public"."submissions"
  as permissive
  for select
  to authenticated
using ((submitted_by_id = auth.uid()));
